<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api,post,labels,type Organization} from '../api'
const orgs=ref<Organization[]>([]),disputes=ref<{id:string;title:string;reason:string;resolved_at:string|null}[]>([]),failed=ref<{id:string;kind:string;attempts:number}[]>([]),error=ref(''),busy=ref(false),note=ref(''),resolution=ref(''),selected=ref('')
async function load(){try{const d=await api<{organizations:Organization[];disputes:typeof disputes.value;failed_tasks:typeof failed.value}>('/admin');orgs.value=d.organizations;disputes.value=d.disputes;failed.value=d.failed_tasks}catch(e){error.value=(e as Error).message}}
async function review(o:Organization,decision:string){if(busy.value)return;busy.value=true;error.value='';try{await post(`/admin/organizations/${o.id}/review`,{decision,note:note.value});note.value='';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function resolve(id:string,outcome:string){if(busy.value)return;busy.value=true;error.value='';try{await post(`/admin/disputes/${id}/resolve`,{outcome,note:resolution.value});selected.value='';resolution.value='';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="container page-section"><div class="page-heading"><div class="eyebrow">COMMUNITY OPERATIONS</div><h1>让信任，有人守护。</h1><p>审核组织身份、处理争议，维护社区交接秩序。</p></div><p v-if="error" class="error" role="alert">{{error}}</p><div class="surface admin-panel"><h2>组织审核</h2><label>本次审核备注<input v-model="note" placeholder="请先线下核验组织身份，再填写审核依据（至少 5 字）" minlength="5" maxlength="1000"/></label><div class="table-scroll"><table><thead><tr><th>组织</th><th>类型</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in orgs" :key="o.id"><td>{{o.name}}</td><td>{{labels[o.kind]}}</td><td><span class="status" :class="o.status">{{labels[o.status]}}</span></td><td><button v-if="o.status!=='approved'" class="button small" :disabled="busy||note.trim().length<5" @click="review(o,'approved')">通过</button><button v-else class="text-button danger" :disabled="busy||note.trim().length<5" @click="review(o,'suspended')">暂停</button></td></tr></tbody></table></div><p v-if="!orgs.length" class="muted">暂无组织。</p></div><div class="surface admin-panel"><h2>交接争议</h2><p v-if="!disputes.length" class="muted">暂无争议。</p><article v-for="d in disputes" :key="d.id" class="dispute-item"><h3>{{d.title}}</h3><p>{{d.reason}}</p><span v-if="d.resolved_at" class="status completed">已处理</span><template v-else><button class="text-button" @click="selected=selected===d.id?'':d.id">填写处理意见</button><div v-if="selected===d.id"><label>处理说明<textarea v-model="resolution" minlength="5" maxlength="1000" required></textarea></label><div class="button-row"><button class="button small" :disabled="busy||resolution.length<5" @click="resolve(d.id,'completed')">恢复已完成记录</button><button class="button small secondary" :disabled="busy||resolution.length<5" @click="resolve(d.id,'cancelled')">取消交接</button></div><p class="form-hint">仅已有接收方确认的记录可以恢复为完成；不能用审核制造交接事实。</p></div></template></article></div><div class="surface admin-panel"><h2>后台失败任务</h2><p v-if="!failed.length" class="muted">暂无进入失败队列的任务。</p><p v-for="f in failed" :key="f.id">{{f.kind}} · 尝试 {{f.attempts}} 次 · {{f.id}}</p></div></section></template>
